class Solution {
public:
    int countPairs(TreeNode* root, int distance) {
        int ans = 0;
        dfs(root, distance, ans);
        return ans;
    }

private:
    vector<int> dfs(TreeNode* node, int distance, int& ans) {
        vector<int> cnt(distance + 1, 0);
        if (!node) return cnt;

        if (!node->left && !node->right) {
            cnt[0] = 1;
            return cnt;
        }

        vector<int> left = dfs(node->left, distance, ans);
        vector<int> right = dfs(node->right, distance, ans);

        vector<int> prefix(distance + 2, 0);
        for (int i = 0; i <= distance; i++) {
            prefix[i + 1] = prefix[i] + right[i];
        }

        for (int d1 = 0; d1 <= distance; d1++) {
            if (left[d1] == 0) continue;
            int maxD2 = distance - d1 - 2;
            if (maxD2 >= 0) {
                ans += left[d1] * prefix[maxD2 + 1];
            }
        }

        for (int d = 1; d <= distance; d++) {
            cnt[d] = left[d - 1] + right[d - 1];
        }

        return cnt;
    }
};
